-- Kashf schema v1; MariaDB 10.1+; import ONLY into the new empty project database.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS schema_versions (version INTEGER PRIMARY KEY, installed_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS learners (id INTEGER UNSIGNED PRIMARY KEY, name VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS subjects (id VARCHAR(32) PRIMARY KEY, name VARCHAR(100) NOT NULL, icon VARCHAR(40) NOT NULL, position INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapters (id VARCHAR(64) PRIMARY KEY, subject_id VARCHAR(32) NOT NULL, name VARCHAR(190) NOT NULL, position INTEGER NOT NULL, FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS topics (id VARCHAR(64) PRIMARY KEY, chapter_id VARCHAR(64) NOT NULL, name VARCHAR(255) NOT NULL, position INTEGER NOT NULL, FOREIGN KEY(chapter_id) REFERENCES chapters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS resources (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, subject_id VARCHAR(32) NOT NULL, resource_key VARCHAR(64) NOT NULL, name VARCHAR(190) NOT NULL, archived INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, UNIQUE(subject_id,resource_key), FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS resource_topics (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, resource_id INTEGER UNSIGNED NOT NULL, topic_key VARCHAR(80) NOT NULL, title VARCHAR(255) NOT NULL, position INTEGER NOT NULL, UNIQUE(resource_id,topic_key), FOREIGN KEY(resource_id) REFERENCES resources(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS activities (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, learner_id INTEGER UNSIGNED NOT NULL DEFAULT 1, resource_topic_id INTEGER UNSIGNED NOT NULL, activity_date DATE NOT NULL, kind VARCHAR(20) NOT NULL, note TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, deleted_at VARCHAR(30) NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(learner_id) REFERENCES learners(id), FOREIGN KEY(resource_topic_id) REFERENCES resource_topics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS assignments (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, learner_id INTEGER UNSIGNED NOT NULL DEFAULT 1, subject_id VARCHAR(32) NOT NULL, title VARCHAR(190) NOT NULL, description TEXT NOT NULL, due_date DATE NOT NULL, completed_at VARCHAR(30) NULL, archived INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(learner_id) REFERENCES learners(id), FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS extra_studies (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, learner_id INTEGER UNSIGNED NOT NULL DEFAULT 1, subject_id VARCHAR(32) NOT NULL, title VARCHAR(190) NOT NULL, report TEXT NOT NULL, reference_text VARCHAR(255) NOT NULL, entry_date DATE NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(learner_id) REFERENCES learners(id), FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS challenges (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, learner_id INTEGER UNSIGNED NOT NULL DEFAULT 1, subject_id VARCHAR(32) NULL, title VARCHAR(190) NOT NULL, report TEXT NOT NULL, entry_date DATE NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(learner_id) REFERENCES learners(id), FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS login_attempts (ip_key VARCHAR(64) PRIMARY KEY, attempts INTEGER NOT NULL, first_at INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
START TRANSACTION;
COMMIT;
